create table if not exists public.account_service_entitlements (id uuid primary key default gen_random_uuid(),account_user_id uuid references auth.users(id) on delete cascade,service_tier text not null check(service_tier in ('business','enterprise')),location_limit integer,enterprise_fleet_enabled boolean not null default false,fleet_enabled boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now()); create unique index if not exists uq_account_service_entitlement on public.account_service_entitlements(account_user_id,service_tier); create table if not exists public.business_growth_signals (id uuid primary key default gen_random_uuid(),business_id uuid references public.businesses(id) on delete cascade,event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); create index if not exists idx_business_growth_signals_business_time on public.business_growth_signals(business_id,created_at desc); alter table public.account_service_entitlements enable row level security; alter table public.business_growth_signals enable row level security; create policy account_service_entitlements_own on public.account_service_entitlements for select to authenticated using(account_user_id=auth.uid()); create policy business_growth_signals_read_authenticated on public.business_growth_signals for select to authenticated using(true); create or replace function public.enable_enterprise_fleet_service(p_user_id uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin insert into public.account_service_entitlements(account_user_id,service_tier,enterprise_fleet_enabled,fleet_enabled) values(p_user_id,'enterprise',true,true) on conflict(account_user_id,service_tier) do update set enterprise_fleet_enabled=true,fleet_enabled=true,updated_at=now() returning id into v_id; return v_id; end; $$;
